{
  "version": "0.2",
  "phases": {
    "install": {
      "runtime-versions": {
        "nodejs": "20"
      }
    },
    "build": {
      "commands": [
        "echo \"Checking environment and working directory...\"",
        "pwd",
        "ls -la",
        "echo \"Node.js version:\"",
        "node --version",
        "echo \"npm version:\"",
        "npm --version",
        "echo \"Checking if package.json exists...\"",
        "test -f package.json && echo \"✅ package.json found\" || echo \"❌ package.json not found\"",
        "echo \"Installing dependencies...\"",
        "npm install",
        "echo \"Checking node_modules structure...\"",
        "ls -la node_modules/.bin/ | head -10",
        "echo \"Checking if TypeScript is installed...\"",
        "npm list typescript || echo \"TypeScript not found in dependencies\"",
        "echo \"Checking if @types/node is installed...\"",
        "npm list @types/node || echo \"@types/node not found in dependencies\"",
        "echo \"Compiling TypeScript...\"",
        "npm run build",
        "echo \"Running tests...\"",
        "npm run test",
        "echo \"Synthesizing CDK templates...\"",
        "npx cdk synth"
      ]
    }
  },
  "artifacts": {
    "base-directory": "cdk.out",
    "files": [
      "**/*"
    ]
  }
}

{
  "version": "0.2",
  "phases": {
    "build": {
      "commands": [
        "echo \"Validating application configurations...\"",
        "npm install",
        "npx ts-node scripts/validate-configs.ts",
        "echo \"Configuration validation completed\""
      ]
    }
  }
}

{
  "version": "0.2",
  "phases": {
    "build": {
      "commands": [
        "echo \"Validating promotion to prod environment...\"",
        "npm install",
        "npx ts-node scripts/validate-deployment.ts -- --environment prod",
        "echo \"Promotion to prod validated successfully\""
      ]
    }
  }
}

{
  "version": "0.2",
  "phases": {
    "build": {
      "commands": [
        "echo \"Validating promotion to staging environment...\"",
        "npm install",
        "npx ts-node scripts/validate-deployment.ts -- --environment staging",
        "echo \"Promotion to staging validated successfully\""
      ]
    }
  }
}

